<script setup lang="ts">import {ref} from 'vue';import {ChevronDown,Copy,Check} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {specificationGroups} from '../data/mock';const open=ref(['Engine','Fluids','Wheels & Tires','Vehicle']);const copied=ref('');const copy=async(v:string)=>{await navigator.clipboard.writeText(v);copied.value=v;setTimeout(()=>copied.value='',1200)};const toggle=(t:string)=>open.value=open.value.includes(t)?open.value.filter(x=>x!==t):[...open.value,t]

</script>
<template><PageHeader title="Specifications" back="/vehicle/bmw-320d"/><div class="container-app max-w-4xl py-7"><p class="eyebrow">BMW 320d Touring</p><h1 class="page-title mt-2">Technical details</h1><p class="mt-3 text-muted">Essential specifications for servicing and ownership.</p><div class="mt-8 space-y-3"><section v-for="g in specificationGroups" class="card overflow-hidden"><button class="flex w-full items-center justify-between p-5 text-left" @click="toggle(g.title)"><h2 class="section-title">{{g.title}}</h2><ChevronDown :size="19" class="transition" :class="{'rotate-180':open.includes(g.title)}"/></button><div v-if="open.includes(g.title)" class="border-t px-5"><div v-for="item in g.items" class="flex items-center justify-between gap-5 border-b py-4 last:border-0"><span class="text-sm text-muted">{{item[0]}}</span><span class="flex items-center gap-2 text-right text-sm font-semibold nums">{{item[1]}}<button v-if="item[0]==='VIN'||item[0]==='Recommended specification'" @click="copy(item[1])" class="grid h-8 w-8 place-items-center rounded-lg text-muted hover:bg-stone-100" :aria-label="`Copy ${item[0]}`"><Check v-if="copied===item[1]" :size="15" class="text-success"/><Copy v-else :size="15"/></button></span></div></div></section></div><p class="mt-6 text-xs leading-5 text-muted">Specifications are shown for prototype purposes. Always confirm service requirements with the vehicle manufacturer or a qualified workshop.</p></div></template>
